/**
 * This behavior provides the common behaviors for all the smart conrol's application header's
 * integrated controls. For example, basic click functionality, keyboard navigations, etc.,
 */

csui.define('smart/behaviors/app.header/app.header.control.behavior',[
  "nuc/lib/jquery",
  "nuc/lib/underscore",
  "nuc/lib/marionette",
  "smart/utils/smart.base",
], function ($, _, Marionette, SmartBase) {
  "use strict";

  var AppHeaderControlBehavior = Marionette.Behavior.extend({
    constructor: function AppHeaderControlBehavior(options = {}, view = {}) {
      this.options = options;
      Marionette.Behavior.prototype.constructor.apply(this, arguments);
      this.view = view;

      this.view.options.otcEl.addEventListener(
        "click",
        _.bind(this._clickHandler, this)
      );
      this.view.options.otcEl.addEventListener(
        "keydown",
        _.bind(this._keyDownHandler, this)
      );

      // uncomment the below code if required in future on window resize
      if (this.view?.options?.aside) {
        $(window).on("resize", _.bind(this._adjustChildView, this));
      }
      this.view.listenToOnce(this.view, "before:destroy", function () {
        $(window).off("resize", this._adjustChildView);
      });
    },

    onShow: function () {
      this._dataChanged();
      this.view.listenTo(
        this.view,
        "data:synced data:synched",
        _.bind(this._dataChanged, this)
      );

      this.view.listenTo(
        this.view,
        "update:progress:values",
        _.bind(this._progressChange, this)
      );
    },

    _adjustChildView: function () {
      // TODO: Need to make it part of options, such that leading application can decide width.
      const LEADING_VIEWS_WIDTH = 400;
      const LEADING_VIEWS_TOP =
        this.view?.options?.parentView?.el?.offsetHeight ?? 64;
      // let childTag = this.view.el;
      let childTag = this.view.options.otcElChild;
      childTag.style.width = LEADING_VIEWS_WIDTH + "px";
      childTag.style.top = LEADING_VIEWS_TOP + "px";

      childTag.style.position = "absolute";

      let el = this.view.options.otcEl;
      let left = el.offsetLeft;

      let targetLeft = left;

      let isRTL = SmartBase.isRTL();

      if (!isRTL) {
        let width = el.offsetWidth;
        targetLeft = left - LEADING_VIEWS_WIDTH + width;
      }

      childTag.style.left = targetLeft + "px";
    },

    /**
     * Handles click events on otc-* element.
     *
     * @param {*} event
     */
    _clickHandler: function (event) {
      let performClickAction = this?.view?.performClickAction ?? true;
      if (performClickAction) {
        if (this.view.options.aside) {
          this._adjustChildView();
        }
        //TODO: need to check whether to handle ctrl + click separately
        this._delegateHandling(event);
      } else {
        event.preventDefault();
      }
    },

    /**
     * Handles keypress events on otc-* element, such that both tab and shift+tab
     * should be leave to otc-header-bar and rest of the events only has to delegate
     * to the leading application's control.
     *
     * @param {*} event
     */
    _keyDownHandler: function (event) {
      if (this.view.options.aside) {
        this._adjustChildView();
      }
      //Do not delegate tab or Shift+tab events to leading application
      event?.keyCode !== 9 && this._delegateHandling(event);
    },

    /**
     * Execute common functionality for all events registered.
     *
     * @param {*} event
     */
    _delegateHandling: function (event) {
      let e = $.Event(event.type);
      e.keyCode = event.keyCode;
      this.view.$el.trigger(e);
    },

    /**
     * If any data has changed at leading application level then honor those changes
     * and act accordingly. For example, if leading application changed the color from
     * default to light/dark, then re-render the view to get respective effects.
     */
    _dataChanged: function () {
      let otcData = this?.view?.otcData ?? {};
      let attrs = {};
      let controlType = this.view.options.type;
      if (controlType) {
        let schema = this.view.options?.SCHEMA_ASSOSIATIONS[controlType];
        let attributes = Object.keys(schema?.attributes || {});
        attributes.forEach((attribute) => {
          if (
            this.view.options.aside &&
            attribute === "className" &&
            otcData[attribute]
          ) {
            this.view.options.child.setAttribute("class", otcData[attribute]);
          } else if (attribute === "overflowValue") {
            attrs["value"] = otcData[attribute];
          } else {
            if (attribute === "iconappearance") {
              let parentViewEl = this.view?.options?.parentView?.el;
              let overflowContainer = parentViewEl?.querySelector(
                "otc-overflow-container"
              );
              if (
                overflowContainer.getAttribute("overflowmenuiconappearance") ===
                ""
              ) {
                overflowContainer.setAttribute(
                  "overflowmenuiconappearance",
                  otcData[attribute] !== undefined &&
                    otcData[attribute] !== "default"
                    ? otcData[attribute]
                    : "light"
                );
              }
            }
            attrs[attribute] =
              otcData[attribute] ?? schema.attributes[attribute];
          }
        });
      }
      Object.keys(attrs).forEach(
        _.bind(function (key) {
          this.view.options.otcEl.setAttribute(key, attrs[key]);
        }, this)
      );
      this.view.render();
    },

    _progressChange: function (progressValues) {
      this.view.options?.otcEl?.setAttribute("from", progressValues?.from);
      this.view.options?.otcEl?.setAttribute("to", progressValues?.to);
    },
  });

  return AppHeaderControlBehavior;
});
