csui.define('smart/controls/node.picker/indicator/node.indicator.icons.view',[
  "nuc/lib/underscore",
  "nuc/lib/jquery",
  "nuc/lib/marionette",
  "nuc/lib/backbone",
  "smart/controls/node.picker/indicator/node.indicator.icons",
  "smart/controls/node.picker/indicator/node.indicator.icons.collection.view",
  "hbs!smart/controls/node.picker/indicator/impl/node.indicator.icons",
  "css!smart/controls/node.picker/indicator/impl/node.indicator.icons",
], function (
  _,
  $,
  Marionette,
  Backbone,
  NodeIndicatorIcons,
  NodeIndicatorCollectionView,
  template
) {
  "use strict";

  var NodeIndicatorView = Marionette.ItemView.extend(
    {
      template,
      class: "smart-node-indicator-wrapper",
      constructor: function NodeIndicatorView(options = {}) {
        Marionette.ItemView.prototype.constructor.apply(this, arguments);
      },

      onRender: function () {
        if (this.options?.collection?.length) {
          this.nodeIndicatorCollectionView = new NodeIndicatorCollectionView({
            collection: this.options.collection,
            ...this.options,
          });

          new Marionette.Region({
            el: this.$el,
          }).show(this.nodeIndicatorCollectionView);
        } else {
          // console.log("nothing to render...");
        }
      },
    },
    {
      getEnabledNodeIndicatorIcons: function (opts) {
        let origModels = [...NodeIndicatorIcons.models];
        let coll = new Backbone.Collection();
        origModels.length &&
          origModels.map(function (model) {
            let enableFun =
              model?.attributes?.enabled ||
              ((o) => {
                return false;
              });
            if (enableFun(opts)) {
              coll.push(model, { silent: true });
            }
          });
        //coll.length && console.log(coll);
        return coll;
      },
    }
  );

  return NodeIndicatorView;
});
